fragments.text:
fragment Fragment on Character {
  status
}

fragment TestAppearances_character on Character {
  episode {
    name
    air_date
  }
}

fragment TestAuthorNotes_note on Note @refetchable(queryName: "TestAuthorNotesPaginationQuery") @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
  cursor: {type: "String"}
) {
  id
  author {
    id
    name
    notes(first: $count, after: $cursor) @connection(key: "TestAuthorNotes_notes") {
      edges {
        node {
          id
          text
        }
      }
    }
  }
}

fragment TestCard_character on Character {
  name
  ...TestCharacterValue_character
}

fragment TestCaughtAppearances_character on Character {
  episode @catch {
    name
  }
}

fragment TestCaughtPrices_asset on Asset {
  price @catch
  listedAt @catch
  page @catch(to: NULL)
}

fragment TestCaughtProfile_character on Character {
  name
  origin {
    name
  }
}

fragment TestCaughtStrict_character on Character @throwOnFieldError {
  species
}

fragment TestCharacterValue_character on Character @inline {
  id
  name
  status
  origin {
    ...TestOriginValue_location
  }
  episode {
    id
    name
  }
}

fragment TestDeferredNotes_character on Character @refetchable(queryName: "TestDeferredNotesPaginationQuery") @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
  cursor: {type: "String"}
) {
  notes(first: $count, after: $cursor) @connection(key: "TestDeferredNotes_notes") {
    edges {
      node {
        id
        ...TestNoteText_note @defer(label: "noteText")
      }
    }
  }
}

fragment TestEdgesNames_character on Character {
  notes(first: 2) @connection(key: "TestEdgesNames_notes") {
    Edges: pageInfo {
      hasNextPage
    }
    edges {
      node {
        id
        text
      }
    }
  }
}

fragment TestFavorite_character on Character {
  id
  name
  favorite
}

fragment TestHeader_character on Character {
  name
  status
  species
  image
  origin {
    name
  }
}

fragment TestHiddenNotes_character on Character @refetchable(queryName: "TestHiddenNotesPaginationQuery") @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
  cursor: {type: "String"}
) {
  TestHiddenNotes_character: name
  TestHiddenNotesPaginationQuery: status
  notes(first: $count, after: $cursor) @connection(key: "TestHiddenNotes_notes") {
    TestHiddenNotes_character: totalCount
    TestHiddenNotesPaginationQuery: totalCount
    edges {
      node {
        id
        text
      }
    }
  }
}

fragment TestHiddenRecentNotes_character on Character @refetchable(queryName: "TestHiddenRecentNotesPaginationQuery") @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
  cursor: {type: "String"}
) {
  notes(last: $count, before: $cursor) @connection(key: "TestHiddenRecentNotes_notes") {
    TestHiddenRecentNotes_character: totalCount
    TestHiddenRecentNotesPaginationQuery: totalCount
    edges {
      node {
        id
        text
      }
    }
  }
}

fragment TestKeyArguments_query on Query @argumentDefinitions(
  ids: {type: "[ID!]!"}
  filter: {type: "FilterCharacter"}
) {
  charactersByIds(ids: $ids) {
    name
  }
  characters(filter: $filter) {
    info {
      count
    }
  }
}

fragment TestLogEdges_connection on NoteConnection {
  edges @required(action: LOG) {
    cursor
  }
}

fragment TestLoggedNotes_character on Character {
  notes(first: 1) {
    totalCount
    ...TestLogEdges_connection
  }
}

fragment TestName_character on Character {
  name
}

fragment TestNamedValue_character on Character @inline {
  name
}

fragment TestNamed_named on Named {
  name
}

fragment TestNoteText_note on Note {
  text
}

fragment TestNotesValue_character on Character @inline @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
) {
  notes(first: $count) {
    totalCount
  }
}

fragment TestNotes_character on Character @refetchable(queryName: "TestNotesPaginationQuery") @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
  cursor: {type: "String"}
) {
  name
  notes(first: $count, after: $cursor) @connection(key: "TestNotes_notes") {
    totalCount
    edges {
      node {
        id
        text
      }
    }
  }
}

fragment TestOriginAndEpisode_character on Character {
  origin {
    name
  }
  episode {
    name
  }
}

fragment TestOriginValue_location on Location @inline {
  id
  name
  dimension
}

fragment TestProfile_character on Character {
  name
  origin @required(action: NONE) {
    name
  }
  status @required(action: LOG)
  image @catch
  location @catch {
    name
    dimension
  }
  gender @catch(to: NULL)
}

fragment TestProgramNames_character on Character @refetchable(queryName: "TestProgramNamesRefetchQuery") {
  testProgramNamesRefetchQuery: origin {
    name
  }
  testCaughtProfile_character: location {
    name
  }
  ...TestCaughtProfile_character
}

fragment TestRecentNotes_character on Character @refetchable(queryName: "TestRecentNotesPaginationQuery") @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
  cursor: {type: "String"}
) {
  notes(last: $count, before: $cursor) @connection(key: "TestRecentNotes_notes") {
    edges {
      node {
        id
        text
      }
    }
  }
}

fragment TestRenamePayload_mutation on Mutation {
  rename(id: $id, name: $name) {
    character {
      id
      name
    }
  }
}

fragment TestRequiredPrice_asset on Asset {
  price @required(action: NONE)
}

fragment TestResultValue_searchResult on SearchResult @inline {
  ... on Character {
    name
    status
  }
  ... on Location {
    name
    dimension
  }
}

fragment TestRootNotes_query on Query @refetchable(queryName: "TestRootNotesPaginationQuery") @argumentDefinitions(
  count: {type: "Int", defaultValue: 2}
  cursor: {type: "String"}
) {
  notes(first: $count, after: $cursor) @connection(key: "TestRootNotes_notes") {
    totalCount
    edges {
      node {
        id
        text
      }
    }
  }
}

fragment TestRow_character on Character {
  name
  status
  image
}

fragment TestScanningValue_character on Character @inline @throwOnFieldError @argumentDefinitions(
  withName: {type: "Boolean!"}
) {
  id
  ...TestNotesValue_character @arguments(count: 1)
  ...TestNamedValue_character @include(if: $withName) @alias(as: "named")
  ... @alias(as: "caughtCharacter") @catch {
    ...TestCharacterValue_character
  }
}

fragment TestStrict_character on Character @throwOnFieldError {
  species
  type @required(action: THROW)
}

fragment TestThrowingOrigin_character on Character @throwOnFieldError {
  origin @required(action: THROW) {
    name
  }
}

fragment TestThrowingPrices_asset on Asset @throwOnFieldError {
  price
  prices
}

fragment testLowercase on Character {
  name
}

fragment testLowercaseRequired on Character {
  origin @required(action: NONE) {
    name
  }
}
